sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float rotation;
uniform float2 offset;
uniform float count;
uniform float angle;
uniform float random;
uniform float seed;
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float2 hash22(float2 p) {
    float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.xx + q.yz) * q.zy);
}
float2 hexLocal(float2 p) {
    float2 r = float2(1.0, 1.7320508);
    float2 h = r * 0.5;
    float2 a = mod(p, r) - h;
    float2 b = mod(p - h, r) - h;
    return dot(a, a) < dot(b, b) ? a : b;
}
half4 main(float2 coord) {
    float unit = size.y / (2.475 * max(count, 0.5));
    float a = radians(angle);
    float cs = cos(a);
    float sn = sin(a);
    float2 c = size * 0.5 + offset;
    float2 p = coord - c;
    p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y) / unit;
    float2 g = hexLocal(p);
    float2 id = floor((p - g) * float2(1.0, 0.5773503) * 2.0 + 0.5);
    float r = radians(rotation + random * 360.0 * (hash12(id + seed * 7.31) - 0.5));
    float rc = cos(r);
    float rs = sin(r);
    float2 q = (p - g) + float2(rc * g.x + rs * g.y, -rs * g.x + rc * g.y);
    q *= unit;
    return image.eval(float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y) + c);
}
